<template>
  <SubHeader
    v-if="!$route.fullPath.includes('/share')"
    name="invoice_details"
    :label="$t('invoices')"
    :back_to_link="'/invoice/dashboard'"
  >
  </SubHeader>
  <BackToSettings
    v-if="!$route.fullPath.includes('/share')"
    :label="$t('invoices')"
    back_to_rotue="/invoice/dashboard"
  />

  <div
    class="row q-px-lg q-pb-lg"
    :class="
      $route.fullPath.includes('/share')
        ? iframe_path
          ? 'share-content'
          : ''
        : iframe_path
          ? 'invoice-content'
          : ''
    "
  >
    <q-card class="col-12 container-padding">
      <q-card-actions class="row">
        <div class="col-12 border-bottom-bdbdbd q-pb-sm">
          <div class="row">
            <div class="col-6 items-center">
              <div class="text-h6 text-bold text-primary flex items-center">
                <InvoiceDetailIcon />
                <span class="invoice-number-padd">
                  {{ $t('invoice') }} #{{
                    invoice_details?.alternate_document_id
                  }}
                </span>
              </div>
            </div>
            <div class="col-6 items-center" style="padding-top: 13px">
              <f-btn class="float-right" @click="shareLinkInvoice">
                <q-icon :name="mdiShare" />
                <span class="q-ml-xs q-mr-sm">{{ $t('share') }}</span>
                <q-tooltip>{{ $t('copy_public_url') }}</q-tooltip>
              </f-btn>
            </div>
          </div>
        </div>

        <div
          v-if="invoice_details"
          class="col-12 mt-4 q-pa-lg text-blue-grey-5"
        >
          <div class="row mb-4">
            <div class="col-3 text-bold">{{ $t('invoice_number') }} :</div>
            <div class="col-3">
              {{ invoice_details?.alternate_document_id }}
            </div>
            <div class="col-3 text-bold">{{ $t('status') }} :</div>
            <div class="col-3 text-uppercase">
              <q-badge
                v-if="invoice_details?.status"
                transparent
                align="middle"
                :color="statusColor(invoice_details?.status)"
              >
                {{ invoice_details?.status }}
              </q-badge>
            </div>
          </div>
          <div class="row mb-4">
            <div class="col-3 text-bold">{{ $t('supplier_name') }} :</div>
            <div class="col-3">{{ invoice_details?.supplier_name }}</div>
            <div class="col-3 text-bold">{{ $t('paid_status') }} :</div>
            <div class="col-3 text-uppercase">
              <q-badge
                transparent
                align="middle"
                :color="statusColor(invoice_details?.paid_status ?? 'Open')"
              >
                {{
                  invoice_details?.paid_status
                    ? invoice_details?.paid_status
                    : 'Open'
                }}
              </q-badge>
            </div>
          </div>
          <div class="row mb-4">
            <div class="col-3 text-bold">{{ $t('total_amount') }} :</div>
            <div class="col-3">{{ invoice_details?.extended_amount }}</div>
            <div class="col-3 text-bold">
              {{ $t('invoice_details_date') }} :
            </div>
            <div class="col-3">
              {{ formatDateTimeZone(invoice_details?.invoice_date, true) }}
            </div>
          </div>
          <div class="row mb-4">
            <div class="col-3 text-bold">{{ $t('purchase_order') }}# :</div>
            <div class="col-3">
              {{ invoice_details?.purchase_order_number }}
            </div>
            <div class="col-3 text-bold">{{ $t('invoice_due_date') }} :</div>
            <div class="col-3">
              {{ formatDateTimeZone(invoice_details?.invoice_due_date, true) }}
            </div>
          </div>
          <div class="row mb-4">
            <div class="col-3 text-bold">{{ $t('discount_term') }} :</div>
            <div class="col-3">{{ invoice_details?.discount_term }}</div>
            <div class="col-3 text-bold">{{ $t('payment_method') }} :</div>
            <div class="col-3">
              {{ showPaymentMethodLabel(invoice_details?.payment_method) }}
            </div>
          </div>
          <div class="row mb-4">
            <div class="col-3 text-bold">{{ $t('electronic_payment') }}# :</div>
            <div class="col-3">
              {{
                displayLastSixDigits(invoice_details?.electronic_payment_number)
              }}
            </div>
            <div class="col-3 text-bold">{{ $t('payment_date') }} :</div>
            <div class="col-3">
              {{ formatDateTimeZone(invoice_details?.payment_date, true) }}
            </div>
          </div>
        </div>

        <!-- invoice pdf iframe -->
        <div class="col-12 iframe-padding">
          <div class="mx-12 q-card mt-10" v-if="iframe_path">
            <iframe
              v-if="!skeletonLoad"
              id="preview_frame"
              :src="iframe_path"
              title="file preview"
              width="100%"
              height="700px"
            ></iframe>
            <q-skeleton
              v-else
              style="width: 100%"
              :animated="false"
              width="100%"
              height="700px"
              class="custom-skeleton"
            ></q-skeleton>
          </div>
        </div>
      </q-card-actions>
    </q-card>
  </div>

  <q-inner-loading :showing="loading" style="z-index: 2">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import BackToSettings from 'src/pages/Settings/Components/BackToSettings.vue';
import { invoiceDashboardStore, useSettingStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { getStatusColor } from 'src/pages/PurchaseOrders/constants.js';
import { mdiShare } from '@quasar/extras/mdi-v6';
import { copyToClipboard } from 'quasar';
import { ApiExceptions } from 'src/exceptions';
import { isEmptyString, isUndefinedOrNull } from 'src/utils/general';
import { useImageAuth } from 'src/composables/useImageAuth';
import { DOC2API_URL } from 'src/pages/APIs';
import axios from 'axios';
import dateUtils from 'src/utils/date';
import { paymentMtdAPOptions } from 'src/supplier/constant';
import InvoiceDetailIcon from 'src/pages/Invoice/page/invoice-detail-icon.vue';
export default defineComponent({
  mixins: [dateUtils],
  components: {
    SubHeader,
    BackToSettings,
    InvoiceDetailIcon,
  },
  mounted() {
    this.init();
  },
  methods: {
    async init() {
      await this.getDetails();
    },
    async getDetails() {
      try {
        this.preview_path = '';
        this.loading = true;

        const invoice_id = this.$route.params.id as string;
        this.id = invoice_id;

        if (
          this.$route.fullPath.includes('/share') &&
          this.$route.query.token
        ) {
          this.token = this.$route.query.token as string;
          try {
            const response = await axios.get(
              `${DOC2API_URL}/supplier_invoice/share/get_details?token=${this.token}`,
            );
            if (response) {
              this.invoice_details = response?.data?.data;
            }
            this.getPreviewSharePath(this.token);
          } catch (err: any) {
            logError(err);
          }
        } else {
          if (invoice_id) {
            await this.getInvoiceDetails(invoice_id);
          }
          await this.getPreviewPathInvoice();
        }
      } catch (err: any) {
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    async getPreviewSharePath(token: string) {
      try {
        const previewPath = this.invoice_details.preview_path as string;

        if (isUndefinedOrNull(previewPath) && isEmptyString(previewPath)) {
          return;
        }

        try {
          this.skeletonLoad = true;
          const alternate_document_id = this.invoice_details
            .alternate_document_id as string;
          const response = await axios.get(
            `${DOC2API_URL}/resource/get_file/${alternate_document_id}?path=${previewPath}&download=false&token=${token}`,
            {
              responseType: 'blob',
            },
          );

          if (response.headers['content-type'] == 'application/json') {
            // if the file is not exist try to get it again after 5 seconds
            return setTimeout(() => {
              this.getInvoicePdfFile();
            }, 5000);
          }
          const url = response.config.url as string;
          this.iframe_path = url;
        } catch (err: any) {
          logError(err);
        } finally {
          this.skeletonLoad = false;
        }
      } catch (err: any) {
        logError(err);
      }
    },
    async getPreviewPathInvoice() {
      try {
        if (
          !isUndefinedOrNull(this.preview_path) &&
          !isEmptyString(this.preview_path)
        ) {
          this.getInvoicePdfFile();
          return;
        }

        try {
          this.skeletonLoad = true;
          const invoice_id = this.$route.params.id as string;

          if (invoice_id) {
            await this.getPreviewPath(invoice_id);
            await this.getInvoicePdfFile();
          }
        } catch (err: any) {
          logError(err);
        } finally {
          this.skeletonLoad = false;
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err);
        const errorFrame = document.getElementById(
          'preview_frame',
        ) as HTMLIFrameElement;
        const errorDoc = errorFrame.contentDocument;
        if (errorDoc) {
          errorDoc.write('<h1>Error</h1><p>Oops!  ' + msg + '.</p>');
          errorDoc.close();
        }
        logError(err);
      }
    },
    async getInvoicePdfFile() {
      try {
        if (
          isUndefinedOrNull(this.preview_path) ||
          isEmptyString(this.preview_path)
        ) {
          return;
        }

        await this.refreshTokenParam();

        try {
          this.skeletonLoad = true;
          const response = await axios.get(
            `${DOC2API_URL}/resource/get_file/${this.invoice_id_path}?path=${this.preview_path}&download=false&${this.tokenQueryParam}`,
            {
              responseType: 'blob',
            },
          );

          if (response.headers['content-type'] == 'application/json') {
            // if the file is not exist try to get it again after 5 seconds
            return setTimeout(() => {
              this.getInvoicePdfFile();
            }, 5000);
          }
          const url = response.config.url as string;
          this.iframe_path = url;
        } catch (e) {
          logError(e);
        } finally {
          this.skeletonLoad = false;
        }
      } catch (err: any) {
        logError(err);
      }
    },
    statusColor(status: string) {
      if (status) {
        return getStatusColor(status.toLowerCase()) || 'primary';
      } else {
        return '';
      }
    },
    async shareLinkInvoice() {
      const route = this.$route.fullPath;
      if (route.includes('/share')) {
        this.shareLink = window.location as any;
        copyToClipboard(this.shareLink).then(() => {
          notify.success(this.$t('copy_to_clipboard'));
        });
      } else {
        try {
          if (this.id) {
            let token = (await this.getInvoiceShareToken(this.id)) as any;
            if (token) {
              const baseUrl = window.location.origin as any;
              this.shareLink = `${baseUrl as string}/supplier_invoice/share/get_details?token=${token as string}`;
              copyToClipboard(this.shareLink).then(() => {
                notify.success(this.$t('copy_to_clipboard'));
              });
            }
            return;
          }
        } catch (err: any) {
          logError(err);
        }
      }
    },
    displayLastSixDigits(character: string) {
      let result;
      if (character && character.length > 6) {
        result = character.slice(-6);
      } else {
        result = character;
      }
      return result;
    },
    formatDate(date: string) {
      return date
        ? dateUtils.methods.formatDateWithPattern(date, 'DD.MM.YYYY')
        : '';
    },
    showPaymentMethodLabel(value: string) {
      let showLabel: string;
      const payment = paymentMtdAPOptions.find(
        (option) => option.value === value,
      ) as any;
      if (payment) {
        showLabel = payment.label;
      } else {
        showLabel = '';
      }
      return showLabel;
    },
  },
  data() {
    return {
      shareLink: ref(''),
      skeletonLoad: ref(false),
      iframe_path: ref(''),
      id: ref(''),
      token: ref(''),
    };
  },
  setup() {
    const invoice_store = invoiceDashboardStore();
    const { loading, invoice_details, preview_path, invoice_id_path } =
      storeToRefs(invoice_store);

    const { getInvoiceDetails, getPreviewPath, getInvoiceShareToken } =
      invoice_store;

    const setting_store = useSettingStore();
    const { datePattern, dateFormatOnly } = setting_store;

    const { tokenQueryParam, refreshTokenParam } = useImageAuth();

    return {
      loading,
      invoice_details,
      preview_path,
      invoice_id_path,
      getInvoiceDetails,
      datePattern,
      dateFormatOnly,
      getPreviewPath,
      getInvoiceShareToken,
      mdiShare,
      tokenQueryParam,
      refreshTokenParam,
    };
  },
});
</script>

